public class MatchTypeFilter : CheckBoxBasedAncillaryFilter<VTMatch> {

	public MatchTypeFilter() : base("Match Type")
    {
	}

	/* @Override */
	protected void createCheckBoxInfos() {
		ItemListener listener = new _Anon_ItemListener_1();

		VTAssociationType[] values = VTAssociationType.values();
		foreach (VTAssociationType status in values) {
			GCheckBox checkBox = new GCheckBox(status.toString(), true);
			checkBox.addItemListener(listener);
			CheckBoxInfo<VTMatch> info = new AssociationTypeCheckBoxInfo(checkBox, status);
			checkBoxInfos.add(info);
		}
	}

//==================================================================================================
// Inner Classes
//==================================================================================================

	private class AssociationTypeCheckBoxInfo : CheckBoxInfo<VTMatch> {

		private VTAssociationType associationType;

		public AssociationTypeCheckBoxInfo(JCheckBox checkBox, VTAssociationType associationType) : base(checkBox)
    {
			this.associationType = associationType;
		}

		/* @Override */
		public bool matchesStatus(VTMatch match) {
			if (!isSelected()) {
				return false;
			}
			return match.getAssociation().getType().equals(associationType);
		}
	}

	internal class _Anon_ItemListener_1 : ItemListener
	{

			/* @Override */
			public void itemStateChanged(ItemEvent e) {
				fireStatusChanged(getFilterStatus());
			}
		
	}

